#!/usr/bin/env node
/*
 * check_icons.js -- structural check of the icon arrays in icons.h.
 *
 * What it checks
 *
 *   Every set in icons.h -- claude's creature (素材/claudecode/*.png) and
 *   CodeBuddy's cat (素材/codebuddy/*.jpg) -- is imported bitmap art
 *   generated by tools/gen_icons.py: LANCZOS downscale to each display
 *   size, luminance threshold >= 128, one static frame per state. For
 *   every expected array it checks:
 *
 *     * the array exists, for both editors at all three sizes
 *     * it declares exactly 1 frame (static art: display.h's frame
 *       stepping and animationDue() must never fire)
 *     * its byte length is exactly one frame of its icon size
 *
 * Why structural, not byte-for-byte
 *
 *   Neither set can be regenerated from public/icons.js: the web client
 *   loads the same art files at runtime and rasterises them with the
 *   browser's canvas resampling, so edge pixels differ by a step from
 *   PIL's LANCZOS. Both ends reading the same art with the same threshold
 *   rule is the parity that matters.
 *
 *   public/icons.js also keeps the retired procedural glyphs (the animated
 *   set claude used before the creature art) as the web client's
 *   load-time fallback. icons.h no longer contains that set, so the old
 *   byte-parity check against it is gone; requiring the icons.js module
 *   here still guards that its SIZES / state constants stay in sync with
 *   the tables checked in icons.h.
 *
 *   It is the firmware's check_layout.cpp that covers icons.h against the
 *   layout; this one covers the expectations the web client shares.
 *
 * Usage
 *   node tools/check_icons.js                 # checks against the firmware icons.h
 *   node tools/check_icons.js /path/to/icons.h
 *
 * Exits 1 on any problem, listing what differs; 0 when all checks pass.
 * Prints ALL CHECKS PASSED only on success -- nothing is printed after it.
 */

'use strict';

const fs = require('fs');
const path = require('path');

const Icons = require(path.join(__dirname, '..', 'public', 'icons.js'));

const STATES = ['THINKING', 'BUSY', 'SUCCESS', 'ERROR', 'ALARM', 'IDLE'];
// Array-name infix per editor, matching gen_icons.py's emission.
const EDITORS = { claude: '', codebuddy: '_CODEBUDDY' };

function usage(stream, code) {
  stream.write(
    'Usage: node tools/check_icons.js [icons.h]\n' +
    '\n' +
    'Structurally check the icon arrays in icons.h (both editors\' imported\n' +
    'bitmap sets): present, single-frame, sized right.\n' +
    'With no argument, checks against ../icons.h (the generated firmware file).\n');
  process.exit(code);
}

// Parse the arrays out of icons.h, the way the compiler would lay them out.
// The header is generated, so a targeted scan is enough -- but the caller
// verifies the expected names separately, so a header whose structure changed
// is reported instead of silently checked as a subset of itself.
function parseIcons(src) {
  const frames = {};
  {
    const re = /^const uint8_t (\w+)_FRAMES = (\d+);/gm;
    let m;
    while ((m = re.exec(src)) !== null) frames[m[1]] = parseInt(m[2], 10);
  }

  const arrays = {};
  {
    const re = /^const uint8_t (\w+)\[\] PROGMEM = \{([\s\S]*?)\};/gm;
    let m;
    while ((m = re.exec(src)) !== null) {
      if (!/^ICON_/.test(m[1])) continue;
      const bytes = (m[2].match(/0x[0-9A-Fa-f]{2}/g) || [])
        .map(tok => parseInt(tok, 16));
      arrays[m[1]] = { bytes, frames: frames[m[1]] || 0 };
    }
  }
  return arrays;
}

function edgeOf(name) {
  return parseInt(name.split('_')[1], 10); // ICON_48_THINKING -> 48
}

function main(argv) {
  if (argv.includes('-h') || argv.includes('--help')) usage(process.stdout, 0);

  // Default to the firmware's generated icons.h, two levels up: Node/tools
  // -> Node -> repo, then into the ESP32 sketch folder.
  const hdr = argv[0] || path.join(__dirname, '..', '..',
                                   'ESP32', 'esp32s3_ai_status_display', 'icons.h');
  if (!fs.existsSync(hdr)) {
    process.stderr.write(`icons.h not found: ${hdr}\n`);
    return 2;
  }
  const arrays = parseIcons(fs.readFileSync(hdr, 'utf8'));

  // One frame of XBM is size * ceil(size/8) bytes, bit 0 = leftmost.
  const bytesPerFrame = size => size * ((size + 7) >> 3);

  const problems = [];
  const counts = {};
  for (const [editor, infix] of Object.entries(EDITORS)) {
    counts[editor] = 0;
    for (const size of Icons.SIZES) {
      const names = [`ICON_${size}${infix}_READY`];
      for (const st of STATES) names.push(`ICON_${size}${infix}_${st}`);
      for (const name of names) {
        const theirs = arrays[name];
        if (!theirs) {
          problems.push(`missing ${editor} array in icons.h: ${name}`);
          continue;
        }
        if (theirs.frames !== 1) {
          problems.push(`${name}: imported art must be single-frame, ` +
                        `icons.h declares ${theirs.frames}`);
        }
        const expected = bytesPerFrame(size);
        if (theirs.bytes.length !== expected) {
          problems.push(`${name}: expected ${expected} bytes (one ` +
                        `${size}x${size} frame), icons.h has ` +
                        `${theirs.bytes.length}`);
        }
        counts[editor]++;
      }
    }
  }

  if (problems.length > 0) {
    for (const p of problems) process.stderr.write(`FAIL: ${p}\n`);
    process.stderr.write(
      `${problems.length} problem(s): icons.h drifted from the expected ` +
      'structure. If the icons changed, regenerate icons.h first ' +
      '(python3 tools/gen_icons.py > icons.h), then re-run this check.\n');
    return 1;
  }

  console.log('ALL CHECKS PASSED');
  console.log(`claude set structural: ${counts.claude} array(s); ` +
              `codebuddy set structural: ${counts.codebuddy} array(s) ` +
              '(imported art, 1 frame each)');
  return 0;
}

process.exit(main(process.argv.slice(2)) || 0);
